package com.example.bandlink.service; import com.example.bandlink.dto.ReportRequest; import com.example.bandlink.entity.*; import com.example.bandlink.repository.*; import org.springframework.stereotype.Service; import java.time.*;
@Service public class ReportService {private final ReportRepository reports;private final UserRepository users;private final Clock clock;public ReportService(ReportRepository r,UserRepository u){reports=r;users=u;clock=Clock.systemDefaultZone();}public void create(Long reporter,ReportRequest r){User u=users.findById(reporter).orElseThrow();reports.save(new Report(u,r.targetType(),r.targetId(),r.reason().trim(),LocalDateTime.now(clock)));}}
